import { useMutation } from '@tanstack/react-query';
import axios from 'axios';
import { SuperAppEncData, SuperAppParams } from '~/entities/super-app/model/types';
import { CBDCAxiosError } from '~/shared/@types/error';
import { MutationOptions } from '~/shared/@types/query';
import { API_URLS } from '~/shared/api/api-urls';
import { resultify } from '~/shared/lib/utils/resultify';

const apiSignVerifyReq = (data: SuperAppEncData) => {
  return resultify(
    axios.get<SuperAppParams>(`${API_URLS.signVerifyReq}?encData=${data.encData}&signature=${data.signature}`),
  );
};

export const useApiSignVerifyReq = (options?: MutationOptions<SuperAppEncData, CBDCAxiosError, SuperAppParams>) => {
  const mutation = useMutation<SuperAppParams, CBDCAxiosError, SuperAppEncData>({
    ...options,
    mutationFn: (data: SuperAppEncData) => apiSignVerifyReq(data),
  });

  return {
    ...mutation,
  };
};
