import { BaseCallbackData, BaseCommandData, BaseEncryptedData } from '~/entities/super-app/model/types';

type Props = BaseEncryptedData &
  BaseCommandData &
  BaseCallbackData & {
    baseUrl: string;
  };

export const generateUrl = (props: Props) => {
  const { baseUrl, encData, signature, command, superAppCallback, resultCode } = props;

  const urlParams = new URLSearchParams();

  if (encData) urlParams.append('encData', encData);
  if (signature) urlParams.append('signature', signature);
  if (command) urlParams.append('command', command);
  if (superAppCallback) urlParams.append('superAppCallback', superAppCallback);
  if (resultCode) urlParams.append('resultCode', resultCode);

  const queryString = urlParams.toString();
  return `${decodeURIComponent(baseUrl)}${queryString ? '?' + queryString : ''}`;
};
